        "subject": "Biology",
        "chapter": "Biotechnology: Principles and Processes",
        "solution": "<p>Repetitive DNA has a base composition different from the bulk genomic DNA, so on density gradient centrifugation it forms a separate peak, called a satellite DNA band, at a different density.</p> <p>Elution recovers DNA from a gel, Southern blotting detects a specific sequence by hybridisation, and PCR amplifies a chosen segment; none of them separates bulk DNA from repetitive DNA.</p> <p>Hence, the correct option is (D).</p>"
