          "<p>Gel electrophoresis is used for amplification of a DNA segment.</p>",
          "<p>PCR is used for isolation and separation of gene of interest.</p>",
          "<p>Plasmid DNA acts as vector to transfer the piece of DNA attached to it.</p>"
