        "subject": "Biology",
        "chapter": "Biotechnology: Principles and Processes",
        "solution": "<p>A plasmid is a small circular DNA that replicates independently in a host, so the piece of DNA attached to it is carried into the host cell. Statement (D) is correct.</p> <p>DNA ligase, not polymerase, joins the gene of interest to the vector; gel electrophoresis separates DNA fragments by size and does not amplify them; PCR amplifies a DNA segment and does not isolate or separate it.</p> <p>Hence, the correct option is (D).</p>"
