        "solution": "<p>A restriction endonuclease recognises a specific palindromic nucleotide sequence in DNA, one that reads the same in the 5′→3′ direction on both strands, and cuts the strands at that site. The Assertion is true.</p> <p>PstI and PvuI are themselves restriction enzymes, and each recognises its own different palindromic sequence. A palindromic sequence does not contain recognition sites for them, so the Reason is false.</p> <p>Hence, the correct option is (C).</p>"
