        "solution": "<p>The first recombinant DNA was constructed by linking a gene encoding antibiotic resistance with a native plasmid (an autonomously replicating, circular, extra-chromosomal DNA) of <em>Salmonella typhimurium</em>.</p> <p>In 1972, Stanley Cohen and Herbert Boyer cut out the piece of DNA carrying the antibiotic-resistance gene with a restriction enzyme and joined it to the cut plasmid of <em>Salmonella typhimurium</em> using DNA ligase, giving the first rDNA.</p> <p>This rDNA was afterwards transferred into <em>E. coli</em>, a closely related bacterium, where it replicated; <em>E. coli</em> served only as the host. <em>Agrobacterium tumefaciens</em> is a natural vector of plant cells, and <em>Mycobacterium</em> was not involved.</p> <p>Hence, the correct option is (D).</p>"
