        "answer": "C",
        "marks": 4,
        "neg": 1,
        "type": "MCQ",
        "subject": "Biology",
        "chapter": "Biotechnology: Principles and Processes",
        "solution": "<p>Plasmids are autonomously replicating, circular, extra-chromosomal DNA, so Assertion (A) is true.</p> <p>Plasmids are usually present in bacterial cells, not in eukaryotic cells (yeast is a rare exception). Reason (R) is false.</p> <p>Hence, the correct option is (C).</p>"
